package com.transiva.app;

import android.app.Activity;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.text.InputType;import android.view.Gravity;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.ProgressBar;import android.widget.ScrollView;import android.widget.Switch;import android.widget.TextView;import android.widget.Toast;import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.net.HttpURLConnection;import java.net.URL;import java.nio.charset.StandardCharsets;import java.util.LinkedHashMap;import java.util.Map;

public class AdminWeatherPricingActivity extends Activity{
 private static final String ENDPOINT="https://transiva.my.id/server/admin_weather_pricing_native.php";private final Handler main=new Handler(Looper.getMainLooper());private final Map<String,Row> rows=new LinkedHashMap<>();private String token="";private ProgressBar loading;private final int NAVY=Color.parseColor("#071426"),BG=Color.parseColor("#F3F8FF");
 @Override protected void onCreate(Bundle b){super.onCreate(b);token=new SessionManager(this).getToken().trim();getWindow().setStatusBarColor(NAVY);getWindow().setNavigationBarColor(NAVY);build();load();}
 private void build(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(16),dp(16),dp(28));root.setBackgroundColor(BG);sc.addView(root);setContentView(sc);LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);TextView back=txt("‹",34,"#0B3A78",true);back.setOnClickListener(v->finish());h.addView(back,new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout t=new LinearLayout(this);t.setOrientation(LinearLayout.VERTICAL);t.addView(txt("Harga Hujan",22,"#0B3A78",true));t.addView(txt("Tambahkan biaya awal sementara saat kondisi hujan",12,"#64748B",false));h.addView(t,new LinearLayout.LayoutParams(0,-2,1));root.addView(h);LinearLayout info=card();info.addView(txt("🌧️ Mode hujan tidak mengubah tarif normal",14,"#0B3A78",true));info.addView(txt("Saat aktif, nominal di bawah ditambahkan ke ongkir awal. Order yang sudah dibuat tetap memakai harga yang sudah terkunci.",12,"#64748B",false),top(6));root.addView(info,top(14));addRow(root,"Transbike","TransRide / motor");addRow(root,"Transcar","Transcar / mobil");addRow(root,"TransPickupBike","TransPickup motor");addRow(root,"TransPickupCar","TransPickup mobil");loading=new ProgressBar(this);root.addView(loading,centered(12));Button save=new Button(this);save.setText("Simpan Harga Hujan");save.setAllCaps(false);save.setTextColor(Color.WHITE);save.setTypeface(Typeface.DEFAULT_BOLD);save.setBackground(gradient("#0B7CFF","#064FB9",16));save.setOnClickListener(v->save());root.addView(save,top(14));}
 private void addRow(LinearLayout root,String service,String label){LinearLayout c=card();LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);copy.addView(txt(label,15,"#0B3A78",true));copy.addView(txt(service,10,"#94A3B8",false));head.addView(copy,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setText("Aktif");head.addView(sw);c.addView(head);c.addView(txt("Tambahan ongkir awal (Rp)",11,"#64748B",false),top(10));EditText amount=new EditText(this);amount.setHint("Contoh 3000");amount.setInputType(InputType.TYPE_CLASS_NUMBER);amount.setSingleLine(true);amount.setPadding(dp(12),0,dp(12),0);amount.setBackground(round("#F9FBFF","#D7E6F8",14));c.addView(amount,new LinearLayout.LayoutParams(-1,dp(48)));root.addView(c,top(10));rows.put(service,new Row(service,sw,amount));}
 private void load(){loading.setVisibility(android.view.View.VISIBLE);new Thread(()->{try{JSONObject j=request("GET",null);main.post(()->{loading.setVisibility(android.view.View.GONE);if(!j.optBoolean("success")){toast(j.optString("message"));return;}JSONArray a=j.optJSONArray("weather_pricing");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;Row r=rows.get(x.optString("service_type"));if(r!=null){r.active.setChecked(x.optInt("is_rain_active")==1);r.amount.setText(String.valueOf(x.optLong("start_surcharge")));}}});}catch(Exception e){main.post(()->{loading.setVisibility(android.view.View.GONE);toast(e.getMessage());});}}).start();}
 private void save(){JSONArray a=new JSONArray();try{for(Row r:rows.values()){JSONObject x=new JSONObject();x.put("service_type",r.service);x.put("is_rain_active",r.active.isChecked()?1:0);String z=r.amount.getText().toString().trim();x.put("start_surcharge",z.isEmpty()?0:Long.parseLong(z));a.put(x);}JSONObject p=new JSONObject();p.put("weather_pricing",a);loading.setVisibility(android.view.View.VISIBLE);new Thread(()->{try{JSONObject j=request("POST",p);main.post(()->{loading.setVisibility(android.view.View.GONE);toast(j.optString("message",j.optBoolean("success")?"Tersimpan":"Gagal"));});}catch(Exception e){main.post(()->{loading.setVisibility(android.view.View.GONE);toast(e.getMessage());});}}).start();}catch(Exception e){toast("Nominal tidak valid");}}
 private JSONObject request(String method,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(ENDPOINT+("GET".equals(method)?"?v="+System.currentTimeMillis():"")).openConnection();c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setRequestProperty("Accept","application/json");c.setRequestProperty("Authorization","Bearer "+token);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}}InputStream is=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();BufferedReader br=new BufferedReader(new InputStreamReader(is,StandardCharsets.UTF_8));StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);br.close();c.disconnect();return new JSONObject(sb.toString());}
 private LinearLayout card(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(14),dp(14),dp(14),dp(14));x.setBackground(round("#FFFFFF","#D7E6F8",18));x.setElevation(dp(2));return x;}private TextView txt(String s,int z,String c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.parseColor(c));v.setIncludeFontPadding(false);if(b)v.setTypeface(Typeface.DEFAULT_BOLD);return v;}private GradientDrawable round(String f,String st,int r){GradientDrawable g=new GradientDrawable();g.setColor(Color.parseColor(f));g.setCornerRadius(dp(r));g.setStroke(dp(1),Color.parseColor(st));return g;}private GradientDrawable gradient(String a,String b,int r){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.parseColor(a),Color.parseColor(b)});g.setCornerRadius(dp(r));return g;}private LinearLayout.LayoutParams top(int m){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(m),0,0);return p;}private LinearLayout.LayoutParams centered(int m){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.gravity=Gravity.CENTER_HORIZONTAL;p.setMargins(0,dp(m),0,0);return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private void toast(String s){Toast.makeText(this,s==null?"Terjadi kesalahan":s,Toast.LENGTH_LONG).show();}static class Row{final String service;final Switch active;final EditText amount;Row(String s,Switch a,EditText e){service=s;active=a;amount=e;}}
}
